(function () {
  var section = document.querySelector(".crays-join-fit-tabs-v1");
  if (!section) return;
  var buttons = Array.prototype.slice.call(section.querySelectorAll("[data-join-fit-tab]"));
  var panels = Array.prototype.slice.call(section.querySelectorAll(".crays-join-fit-tabs-v1__panel"));

  function getTargetIndex(button) {
    var index = Number(button.getAttribute("data-join-fit-tab"));
    return Number.isNaN(index) ? 0 : index;
  }

  function activate(index) {
    buttons.forEach(function (button) {
      var active = getTargetIndex(button) === index;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-selected", active ? "true" : "false");
      button.setAttribute("tabindex", active ? "0" : "-1");
    });
    panels.forEach(function (panel, panelIndex) {
      var active = panelIndex === index;
      panel.classList.toggle("is-active", active);
      panel.hidden = !active;
    });
  }

  buttons.forEach(function (button, visualIndex) {
    button.addEventListener("click", function () {
      activate(getTargetIndex(button));
    });
    button.addEventListener("keydown", function (event) {
      var nextVisualIndex = visualIndex;
      if (event.key === "ArrowRight" || event.key === "ArrowDown") nextVisualIndex = (visualIndex + 1) % buttons.length;
      if (event.key === "ArrowLeft" || event.key === "ArrowUp") nextVisualIndex = (visualIndex - 1 + buttons.length) % buttons.length;
      if (event.key === "Home") nextVisualIndex = 0;
      if (event.key === "End") nextVisualIndex = buttons.length - 1;
      if (event.key === " " || event.key === "Enter") {
        event.preventDefault();
        activate(getTargetIndex(button));
        return;
      }
      if (nextVisualIndex !== visualIndex) {
        event.preventDefault();
        activate(getTargetIndex(buttons[nextVisualIndex]));
        buttons[nextVisualIndex].focus();
      }
    });
  });

  document.querySelectorAll("[data-join-fit-jump]").forEach(function (link) {
    link.addEventListener("click", function () {
      var index = Number(link.getAttribute("data-join-fit-jump"));
      if (!Number.isNaN(index)) activate(index);
    });
  });
})();

